package com.raceforge.backend.training.entity;

import com.raceforge.backend.account.entity.User;
import com.raceforge.backend.medical.entity.MedicalRecord;
import jakarta.persistence.*;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.List;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

/**
 * Immutable post-training observations plus the independently updated veterinary review state.
 * The session key enforces one assessment per session. No schema is generated by this entity.
 */
@Entity
@Table(name = "Training_Session_Assessment")
public class TrainingSessionAssessment {
    @Id
    @Column(name = "session_id", length = 20, updatable = false)
    private String sessionId;

    @MapsId
    @OneToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "session_id", nullable = false)
    private TrainingSession session;

    @Column(name = "checklist_version", nullable = false, length = 40)
    private String checklistVersion;

    @Column(name = "passed_count", nullable = false)
    private int passedCount;

    @Enumerated(EnumType.STRING)
    @Column(name = "base_alert_level", nullable = false, length = 30)
    private TrainingAssessmentAlertLevel baseAlertLevel;

    @Enumerated(EnumType.STRING)
    @Column(name = "alert_level", nullable = false, length = 30)
    private TrainingAssessmentAlertLevel alertLevel;

    // The fixed versioned codes contain no commas. A scalar preserves the three-entity model.
    @Column(name = "trigger_codes", nullable = false, length = 500)
    private String triggerCodes = "";

    @Enumerated(EnumType.STRING)
    @Column(name = "review_status", nullable = false, length = 30)
    private TrainingAssessmentReviewStatus reviewStatus = TrainingAssessmentReviewStatus.NOT_REQUIRED;

    @Enumerated(EnumType.STRING)
    @Column(name = "notification_status", nullable = false, length = 40)
    private TrainingAssessmentNotificationStatus notificationStatus = TrainingAssessmentNotificationStatus.NOT_REQUESTED;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "assessor_id", nullable = false)
    private User assessor;

    @JdbcTypeCode(SqlTypes.LOCAL_DATE_TIME)
    @Column(name = "assessed_at", nullable = false)
    private LocalDateTime assessedAt;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "linked_medical_record_id")
    private MedicalRecord linkedMedicalRecord;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "reviewed_medical_record_id")
    private MedicalRecord reviewedMedicalRecord;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "reviewed_by")
    private User reviewedBy;

    @JdbcTypeCode(SqlTypes.LOCAL_DATE_TIME)
    @Column(name = "resolved_at")
    private LocalDateTime resolvedAt;

    @Version
    @Column(name = "version", nullable = false)
    private Long version;

    public TrainingSessionAssessment() {
    }

    public String getSessionId() { return sessionId; }
    public void setSessionId(String value) { sessionId = value; }
    public TrainingSession getSession() { return session; }
    public void setSession(TrainingSession value) {
        session = value;
        sessionId = value == null ? null : value.getSessionId();
    }
    public String getHorseId() {
        return session == null || session.getHorse() == null ? null : session.getHorse().getHorseId();
    }
    public String getChecklistVersion() { return checklistVersion; }
    public void setChecklistVersion(String value) { checklistVersion = value; }
    public int getPassedCount() { return passedCount; }
    public void setPassedCount(int value) { passedCount = value; }
    public int getFailedCount() { return TrainingAssessmentCriterion.values().length - passedCount; }
    public TrainingAssessmentAlertLevel getBaseAlertLevel() { return baseAlertLevel; }
    public void setBaseAlertLevel(TrainingAssessmentAlertLevel value) { baseAlertLevel = value; }
    public TrainingAssessmentAlertLevel getAlertLevel() { return alertLevel; }
    public void setAlertLevel(TrainingAssessmentAlertLevel value) { alertLevel = value; }
    public List<String> getTriggerCodes() {
        return triggerCodes == null || triggerCodes.isBlank()
                ? List.of() : Arrays.asList(triggerCodes.split(","));
    }
    public void setTriggerCodes(List<String> value) {
        triggerCodes = value == null ? "" : String.join(",", value);
    }
    public TrainingAssessmentReviewStatus getReviewStatus() { return reviewStatus; }
    public void setReviewStatus(TrainingAssessmentReviewStatus value) { reviewStatus = value; }
    public TrainingAssessmentNotificationStatus getNotificationStatus() { return notificationStatus; }
    public void setNotificationStatus(TrainingAssessmentNotificationStatus value) { notificationStatus = value; }
    public User getAssessor() { return assessor; }
    public void setAssessor(User value) { assessor = value; }
    public LocalDateTime getAssessedAt() { return assessedAt; }
    public void setAssessedAt(LocalDateTime value) { assessedAt = value; }
    public MedicalRecord getLinkedMedicalRecord() { return linkedMedicalRecord; }
    public void setLinkedMedicalRecord(MedicalRecord value) { linkedMedicalRecord = value; }
    public String getLinkedMedicalRecordId() {
        return linkedMedicalRecord == null ? null : linkedMedicalRecord.getMedicalRecordId();
    }
    public MedicalRecord getReviewedMedicalRecord() { return reviewedMedicalRecord; }
    public void setReviewedMedicalRecord(MedicalRecord value) { reviewedMedicalRecord = value; }
    public String getReviewedMedicalRecordId() {
        return reviewedMedicalRecord == null ? null : reviewedMedicalRecord.getMedicalRecordId();
    }
    public User getReviewedBy() { return reviewedBy; }
    public void setReviewedBy(User value) { reviewedBy = value; }
    public LocalDateTime getResolvedAt() { return resolvedAt; }
    public void setResolvedAt(LocalDateTime value) { resolvedAt = value; }
    public Long getVersion() { return version; }
    public void setVersion(Long value) { version = value; }
}
